import { migrate } from 'drizzle-orm/mysql2/migrator';
import { logger } from '../config/logger.js';
import { closeDb, db } from './client.js';

/** Applies pending SQL migrations from src/db/migrations (generated by `npm run db:generate`). */
async function main() {
  logger.info('Running migrations…');
  await migrate(db, {
    migrationsFolder: new URL('./migrations', import.meta.url).pathname.replace(/^\/(\w:)/, '$1'),
  });
  logger.info('Migrations complete');
}

main()
  .catch((err: unknown) => {
    logger.fatal({ err }, 'Migration failed');
    process.exitCode = 1;
  })
  .finally(() => closeDb());
